use std::env;

struct Config {
    db_url: String,
    port: u16,
}

impl Config {
    fn from_env() -> Result<Config, String> {
        Ok(Config {
            db_url: env::var("DATABASE_URL").map_err(|_| "DATABASE_URL missing")?,
            port: env::var("PORT").ok().and_then(|p| p.parse().ok()).unwrap_or(8080),
        })
    }
}

fn main() {
    // fail fast at boot; never log secrets
    match Config::from_env() {
        Ok(c) => println!("listening on {} (db configured: {})", c.port, !c.db_url.is_empty()),
        Err(e) => eprintln!("config error: {e}"),
    }
}

