fn verdict(item: &str) -> &str {
    match item {
        i if i.contains("env at boot") => "SAFE",
        i if i.contains("logged") => "LEAK",
        i if i.contains("binary") => "LEAK",
        i if i.contains("allowlist") => "SAFE",
        i if i.contains("wildcard") => "LEAK",
        _ => "review",
    }
}

fn main() {
    for i in [
        "secret read from env at boot",
        "secret logged in debug line",
        "secret baked into the binary",
        "CORS allowlist of two known origins",
        "CORS wildcard with credentials",
    ] {
        println!("{}: {}", i, verdict(i));
    }
}
